import re

def _norm(recs):
    keys = []
    for r in recs:
        for k in r:
            if k not in keys:
                keys.append(k)
    return [{k: r.get(k, '') for k in keys} for r in recs]

def parse(lines):
    skip = []
    summary = {}
    sl = []
    settings = []
    setl = []
    applied = []
    appl = []
    filt = []
    fl = []
    groups = []
    gl = []
    scope = None
    sub = None
    cur = None
    frec = None
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        ind = len(l) - len(l.lstrip())
        if re.match(r'^-+$', s):
            skip.append(i)
            continue
        if ind == 0 and (s.startswith('Microsoft (R)') or 'All rights reserved' in s):
            skip.append(i)
            continue
        if ind == 0:
            m = re.match(r'^(COMPUTER|USER) SETTINGS$', s)
            if m:
                scope = m.group(1).title()
                cur = {'Scope': scope}
                settings.append(cur)
                sub = None
                skip.append(i)
                continue
            m = re.match(r'^Created on (.+)$', s)
            if m:
                summary['Created on'] = m.group(1)
                sl.append(i)
                continue
            m = re.match(r'^RSOP data for (.+?) on (.+?) : (.+)$', s)
            if m:
                summary['User'] = m.group(1)
                summary['Computer'] = m.group(2)
                summary['Mode'] = m.group(3)
                sl.append(i)
                continue
            m = re.match(r'^(.+?):\s+(.*)$', s)
            if m:
                summary[m.group(1)] = m.group(2)
                sl.append(i)
            continue
        if scope is None:
            continue
        if ind <= 4:
            if s.startswith('Applied Group Policy Objects'):
                sub = 'applied'
                skip.append(i)
            elif 'not applied' in s:
                sub = 'filtered'
                skip.append(i)
            elif 'security groups' in s:
                sub = 'groups'
                skip.append(i)
            elif sub is None and re.match(r'^[A-Z]{1,3}=', s):
                cur['Distinguished Name'] = s
                setl.append(i)
            else:
                m = re.match(r'^(.+?):\s+(.*)$', s)
                if m:
                    cur[m.group(1)] = m.group(2)
                    setl.append(i)
            continue
        if sub == 'applied':
            applied.append({'Scope': scope, 'GPO': s})
            appl.append(i)
        elif sub == 'groups':
            groups.append({'Scope': scope, 'Group': s})
            gl.append(i)
        elif sub == 'filtered':
            m = re.match(r'^(.+?):\s+(.*)$', s)
            if ind > 8 and m and frec is not None:
                frec[m.group(1)] = m.group(2)
            else:
                frec = {'Scope': scope, 'GPO': s}
                filt.append(frec)
            fl.append(i)
    blocks = []
    if summary:
        blocks.append({'name': 'summary', 'kind': 'kv', 'lines': sl, 'records': [summary]})
    if settings:
        blocks.append({'name': 'settings', 'kind': 'table', 'lines': setl, 'records': _norm(settings)})
    if applied:
        blocks.append({'name': 'applied_gpos', 'kind': 'table', 'lines': appl, 'records': applied})
    if filt:
        blocks.append({'name': 'filtered_gpos', 'kind': 'table', 'lines': fl, 'records': _norm(filt)})
    if groups:
        blocks.append({'name': 'security_groups', 'kind': 'table', 'lines': gl, 'records': groups})
    return {'blocks': blocks, 'skip': skip}
